  if #old~=1 or old[1].map~="FR_SIX_ISLAND_RUIN_VALLEY" or old[1].offset~=80 then return end
  local rows={{map="FR_SIX_ISLAND_GREEN_PATH",offset=0},{map="FR_SIX_ISLAND",offset=40},{map="FR_SIX_ISLAND_RUIN_VALLEY",offset=80}}
