local IDS={
  firered={repelVar=0x4020},
  emerald={repelVar=0x4021},
}
local function ids()
  local GV=require("src.core.GameVersion")
  local game=GV.get()
  if GV.layout(game)=="rse" then
    return {repelVar=require("src.core.game3.constants").of(game):var("VAR_REPEL_STEP_COUNT")}
  end
  return IDS[game] or IDS.firered
end
local FLAGS=nil
do local okFM,modF=pcall(require,"src.core.game3.scripting.flags") if okFM then FLAGS=modF end end
function M.move(row,state,rng)
  local choices={};for _,id in ipairs(row.maps) do if id~=state.map then choices[#choices+1]=id end end
  if #choices==0 then choices=row.maps end
  state.map=choices[(rng()%#choices)+1]
end
function M.install(mod,rows)
  local Runtime=require("src.mods.Runtime")
